package com.example.arfas

/** App-authored Hindi wording; original source excerpts remain separately labelled. Review locally. */
object ArogyaHindi {
    fun instruction(step: ArogyaStep, kind: ArogyaKind): String = when(step.id) {
        "prepare" -> "परिवार को विज़िट का उद्देश्य बताएं और अनुमति लें। रजिस्टर, एमसीपी कार्ड और उपकरण जांचें। फोटो या आवाज़ रिकॉर्ड करने से पहले अनुमति लें।"
        "baby_danger" -> "पहले नवजात में खतरे के लक्षण पूछें और देखें: दूध न पी पाना, कमज़ोर रोना या ढीलापन, तेज़ या कठिन सांस, छूने पर गर्म या ठंडा लगना, हथेलियों या तलवों में पीलापन। कोई लक्षण हो तो चिंता चुनें। जांच न कर सकें तो पता नहीं चुनें। तुरंत स्वास्थ्य केंद्र में जांच की व्यवस्था करें; सूची पूरी होने का इंतज़ार न करें।"
        "mother_danger" -> "मां से अधिक रक्तस्राव, बुखार, बदबूदार स्राव या होश कम होने के बारे में पूछें। लक्षण हो तो चिंता चुनें और अपनी रेफरल व्यवस्था से तत्काल जांच की व्यवस्था करें।"
        "child_danger" -> "पूछें: बच्चा पी या स्तनपान नहीं कर पा रहा, सब उल्टी कर देता है, दौरे हैं, असामान्य नींद या बेहोशी है, तेज़ बुखार है, मल में खून है, या सांस तेज़ या कठिन है। कोई लक्षण हो तो चिंता चुनें और तत्काल जांच की व्यवस्था करें। सूची पूरी होने का इंतज़ार न करें।"
        "feeding" -> if(kind==ArogyaKind.NEWBORN) "दूध पिलाने और बच्चे को गर्म रखने के बारे में पूछें। कठिनाइयां नोट्स में लिखें। फोटो से यह न मानें कि बच्चा पर्याप्त दूध पी रहा है।" else "कार्ड से बच्चे की उम्र की पुष्टि करें। पूछें कि बच्चा क्या खाता और पीता है। चिंताएं लिखें और उम्र के अनुसार स्रोत देखें।"
        "measure" -> "अपने प्रशिक्षण और उपकरणों से वजन और तापमान मापें। इकाई सहित नोट्स में लिखें। जन्म के टीकों के लिए एमसीपी कार्ड देखें। फोटो से माप का अनुमान न लगाएं।"
        "counsel" -> "परिवार को नवजात के खतरे के लक्षण समझाएं। उनसे पूछें कि वे कब और कहां मदद लेंगे। सवाल और बाकी चिंताएं लिखें।"
        "card" -> "परिवार के साथ कार्ड पर दर्ज वृद्धि, टीकाकरण और अगली मुलाकात देखें। जो लिखा है वही दर्ज करें। अस्पष्ट बात एएनएम से जांचवाएं।"
        "play" -> "खेल, बच्चे के साथ बातचीत और घर की सुरक्षा पर चर्चा करें। परिवार के सवाल और देखभाल में कठिनाइयां लिखें।"
        "concern" -> "नई या बढ़ती तकलीफ और तत्काल मदद की जरूरत पूछें। जरूरत हो तो स्थानीय रेफरल व्यवस्था का उपयोग करें। यह फॉलो-अप रिकॉर्ड है, अपने आप बीमारी पहचानने का साधन नहीं।"
        "plan" -> "परिवार के साथ स्वास्थ्यकर्मी की मौजूदा सलाह पढ़ें। अगली मुलाकात, पहुंचने में कठिनाई और सवाल लिखें। दवा या खुराक न बनाएं या बदलें।"
        "support" -> "जरूरी मदद लिखें: साथ जाना, यातायात की व्यवस्था, एएनएम से बात या अगली सेवा तक पहुंचने में सहायता।"
        "record" -> "कार्ड और रजिस्टर में विज़िट दर्ज करें। परिवार और लागू कार्यक्रम या सुपरवाइज़र की योजना के अनुसार अगली तारीख और उद्देश्य की पुष्टि करें।"
        else -> step.instruction
    }
}
